-- Conversation evidence and permissions across every level; no production fixtures survive.
begin;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where active and personnel_category='ceo' limit 1),true);
set local role authenticated;
do $$
declare shareholder uuid;outsider uuid;ceo uuid;manager uuid;supervisor uuid;op uuid;root uuid;mt uuid;st uuid;ot uuid;t uuid;assigners uuid[];assignees uuid[];i integer;first_id bigint;retry_id bigint;reply_id bigint;before_cursor bigint;progress_cursor bigint;retry_key uuid;number_notifications integer;failed boolean;
begin
 select ceo_user_id into ceo from public.task_governance;
 select id into shareholder from public.profiles where active and personnel_category='shareholder' order by full_name limit 1;
 select id into outsider from public.profiles where active and personnel_category='shareholder' and id<>shareholder limit 1;
 select id,corporate_manager_id into op,supervisor from public.profiles where active and role='operator' and full_name not like '[MOC]%' limit 1;
 select corporate_manager_id into manager from public.profiles where id=supervisor;
 assigners:=array[shareholder,ceo,manager,supervisor];assignees:=array[ceo,manager,supervisor,op];
 for i in 1..4 loop
 perform set_config('request.jwt.claim.sub',assigners[i]::text,true);
 t:=public.create_operation_task(jsonb_build_object('title','TRANSIENT-CHAT-'||i,'assigned_to',assignees[i],'due_at',now(),'parent_task_id',case i when 1 then null when 2 then root when 3 then mt else st end));
 if i=1 then root:=t;elsif i=2 then mt:=t;elsif i=3 then st:=t;else ot:=t;end if;
 select last_activity_id into before_cursor from public.operation_tasks where id=t;
 first_id:=public.send_operation_task_message(t,'Instructions from the task assigner',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',assignees[i]::text,true);
 if not exists(select 1 from public.operation_task_conversation where id=first_id and author_name is not null and body='Instructions from the task assigner') then raise exception 'Assignee cannot read instruction or author';end if;
 retry_key:=gen_random_uuid();reply_id:=public.send_operation_task_message(t,'Please clarify the required result',retry_key);
 select count(*) into number_notifications from public.notifications;
 retry_id:=public.send_operation_task_message(t,'Please clarify the required result',retry_key);
 if retry_id<>reply_id or (select count(*) from public.operation_task_conversation where task_id=t)<>2 or (select count(*) from public.notifications)<>number_notifications then raise exception 'Retry duplicated message or notifications';end if;
 failed:=false;begin perform public.send_operation_task_message(t,'Different text with same identifier',retry_key);exception when raise_exception then failed:=true;end;if not failed then raise exception 'Retry key reused for a different message';end if;
 if not exists(select 1 from public.operation_tasks where id=t and status='pending' and progress=0) then raise exception 'Chat changed task progress or status';end if;
 -- The progress snapshot remains valid after chat-only events.
 perform public.update_operation_task(t,'Recorded separately from the conversation',10,'in_progress','[]',before_cursor);
 if i=4 then select last_activity_id into progress_cursor from public.operation_tasks where id=t;end if;
 end loop;
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 perform public.mark_operation_task_seen(ot,progress_cursor);
 perform set_config('request.jwt.claim.sub',op::text,true);
 first_id:=public.send_operation_task_message(ot,'Which inspection point?',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 if not exists(select 1 from public.operation_task_inbox where id=ot and has_updates) then raise exception 'New message did not set task badge';end if;
 perform public.mark_operation_task_messages_seen(ot,first_id);
 if exists(select 1 from public.operation_task_inbox where id=ot and has_updates) then raise exception 'Read conversation did not clear chat-only badge';end if;
 perform set_config('request.jwt.claim.sub',op::text,true);
 perform public.update_operation_task(ot,'Real progress must remain unread',20,'in_progress','[]');
 reply_id:=public.send_operation_task_message(ot,'Additional question',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 perform public.mark_operation_task_messages_seen(ot,reply_id);
 if not exists(select 1 from public.operation_task_inbox where id=ot and has_updates) then raise exception 'Reading chat hid unread progress';end if;
 perform public.mark_operation_task_seen(ot,(select last_activity_id from public.operation_tasks where id=ot));
 perform set_config('request.jwt.claim.sub',op::text,true);
 reply_id:=public.send_operation_task_message(ot,'Newer unread question',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 perform public.mark_operation_task_messages_seen(ot,first_id);
 if not exists(select 1 from public.operation_task_inbox where id=ot and has_updates) then raise exception 'Old chat cursor hid a newer message';end if;
 perform set_config('request.jwt.claim.sub',manager::text,true);
 if not exists(select 1 from public.operation_task_conversation where task_id=ot) then raise exception 'Linked leadership lost evidence';end if;
 failed:=false;begin perform public.send_operation_task_message(ot,'Unauthorized ancestor reply',gen_random_uuid());exception when raise_exception then failed:=true;end;if not failed then raise exception 'Ancestor sent as participant';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 if exists(select 1 from public.operation_task_conversation where task_id=ot) then raise exception 'Unrelated user can read messages';end if;
 failed:=false;begin perform public.send_operation_task_message(ot,'Unauthorized outsider message',gen_random_uuid());exception when raise_exception then failed:=true;end;if not failed then raise exception 'Outsider sent message';end if;
 perform set_config('request.jwt.claim.sub',op::text,true);
 if exists(select 1 from public.operation_task_conversation where task_id in(root,mt,st)) then raise exception 'Operator sees leadership conversations';end if;
 failed:=false;begin perform public.send_operation_task_message(ot,'   ',gen_random_uuid());exception when raise_exception then failed:=true;end;if not failed then raise exception 'Empty message accepted';end if;
 failed:=false;begin perform public.send_operation_task_message(ot,repeat('x',10001),gen_random_uuid());exception when raise_exception then failed:=true;end;if not failed then raise exception 'Oversize message accepted';end if;
 if has_table_privilege('authenticated','public.operation_task_activity','update') or has_table_privilege('authenticated','public.operation_task_activity','delete') or has_function_privilege('anon','public.send_operation_task_message(uuid,text,uuid)','execute') then raise exception 'Evidence permissions unsafe';end if;
 perform public.update_operation_task(ot,'Task completed',100,'completion_requested','[]');
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 perform public.review_operation_task(ot,'approve','Verified complete');
 reply_id:=public.send_operation_task_message(ot,'Retained clarification after completion',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',op::text,true);
 if not exists(select 1 from public.operation_task_conversation where id=reply_id) or not exists(select 1 from public.operation_tasks where id=ot and status='completed' and progress=100) then raise exception 'Archived conversation lost or task reopened';end if;
end $$;
rollback;
select 'PASS: bilateral chat at all four hierarchy levels, retained authors/evidence, retry deduplication, RLS, archived access, independent read cursors and chat-safe progress concurrency; fixtures rolled back' as result;
